fix.html:
ModelBone* parent = mesh-&gt;getParentBoneProperty();   // null only for an XNB mesh whose file names no parent
Matrix meshWorld = transforms[parent != nullptr ? parent-&gt;getIndexProperty() : 0] * world;
for (Effect* effect : mesh-&gt;getEffectsProperty()) {
    // IEffectMatrices covers BasicEffect and the other stock effects, including the PbrEffect and
    // SkinnedPbrEffect that glTF and converted .cnj models use; a dynamic_cast&lt;BasicEffect*&gt; would skip them.
    if (auto* matrices = dynamic_cast&lt;IEffectMatrices*&gt;(effect)) {
        matrices-&gt;setWorldProperty(meshWorld);
        matrices-&gt;setViewProperty(view);
        matrices-&gt;setProjectionProperty(projection);
    }
}

